import logging
import re
import time

from taf.hw.rf_attenuator.attenuator_class import Attenuator
from taf.hw.rf_attenuator.utils.telnet import TelnetClient
from taf.hw.rf_attenuator.exceptions import AttenuationReadError


class Hytem(Attenuator):
    MAX_SUPPORTED_ATTENUATION = 127
    MIN_SUPPORTED_ATTENUATION = 0

    def __init__(self, ip, port=10001, min_attenuation=None, max_attenuation=None):
        super(Hytem, self).__init__()
        self.ip = ip
        self.port = port
        self.conns = {}
        self.min_attenuation = self._validate_min_attenuation(min_attenuation, self.MIN_SUPPORTED_ATTENUATION)
        self.max_attenuation = self._validate_max_attenuation(max_attenuation, self.MAX_SUPPORTED_ATTENUATION)

    def connect(self, **kwargs):
        """
        Establish connection with attenuation controller
        allowing to change attenuation on specific RF-port of that device

        Hytem handles 4 RF-ports at 4 predefined ports: 10001, 10002, 10003, 10004
        """
        if 'rf_ports_at_attenuator' in kwargs:
            ports = kwargs['rf_ports_at_attenuator']
        else:
            ports = range(0, 4)

        for port_id in ports:
            conn = TelnetClient()
            conn.connect(self.ip, self.port + port_id)
            self.conns[port_id] = conn

    def _refresh_attenuator_port(self, port_id):
        """
        Refresh connection with attenuation controller for a specific port_id
        :param port_id: rf_attenuator's port id (integer value in {0,1,2,3})
        :return: None
        """
        conn = self.conns.pop(port_id)
        conn.close_connection()
        del conn
        # mandatory to wait
        time.sleep(1)
        conn = TelnetClient()
        conn.connect(self.ip, self.port + port_id)
        self.conns[port_id] = conn

    def disconnect(self, **kwargs):
        """
        Release connection with attenuation controller
        """
        if 'rf_ports_at_attenuator' in kwargs:
            rf_ports = kwargs['rf_ports_at_attenuator']
            for rf_port in rf_ports:
                conn = self.conns.pop(rf_port)
                conn.close_connection()
        else:
            for connection in self.conns.keys():
                self.conns[connection].close_connection()
            self.conns.clear()

    def _set_single_port_decibel_attenuation(self, rf_port_address, attenuation_value):
        """
        Set attenuation with command of following syntax:
        ATT x yyy
        Sets the attuenation value of port x in 0.1dB
        x number of port (0 for TCP 10001, 1 for TCP 10002 ...)
        yyy attenuation in 0.1dB, no comma allowed, should always be written over 3 digits (e.g. 010 instead of 10)
            :param rf_port_address: 0..3
            :param attenuation_value: float or int in dB
            :return: None
        """
        self._refresh_attenuator_port(rf_port_address)

        attenuation_value = self._provide_correct_att_format(attenuation_value)
        cmd = "ATT {} {}".format(rf_port_address, attenuation_value)
        self._write(cmd, rf_port_address)
        logging.info('Port ID {} value set to {} dB.'.format(rf_port_address, attenuation_value))

    def _write(self, cmd, port_id, refresh=True):
        if refresh:
            self._refresh_attenuator_port(port_id)
        conn = self.conns[port_id]
        try:
            conn.write_command(cmd)
            time.sleep(2)  # mandatory to wait
        except IOError as e:
            logging.warning("Write cmd failed with error : {}".format(e))

    def read_port_attenuation(self, port):
        """
        Read attenuation value at port_id
        :param port: rf_attenuator's port id (integer value in {0,1,2,3})
        :return: attenuation value (type : str)
        """
        for i in range(6):  # mandatory 3 times
            self._write('STA?', port, refresh=False)
            output = self._read(port)
            if output:
                read_val = output.split()[-1]
                if read_val not in (r'?', r'', None, r'\n', r'\t', r'\s'):
                    try:
                        return float(read_val) / 10
                    except ValueError:
                        pass
        raise AttenuationReadError("Could not read attenuation value for port {}.".format(port))

    def _read(self, port_id):
        conn = self.conns[port_id]
        try:
            output = conn.read()
            return output
        except IOError as e:
            logging.warning("Read very eager failed with error : {}".format(e))

    def _provide_correct_att_format(self, att_value):
        """Converts given numeric value to a three digit string, where last digit is a decimal part.
        Throws exception if decimal part length exceeds one digit or whole number length exceeds three digits.
        If whole number length is below three digits, value is topped up with zeros added on the left side.
        Example:
              0.01  -> 001
                 1  -> 010
                10  -> 100
        :param att_value - integer or float with one decimal place
        :return: attenuation value in a format suitable for Hytem rf_attenuator (str) """
        if isinstance(att_value, float):
            att_string = str(att_value)
            regex_determine_decimal_part_length = re.compile(r'(\d+\.\d)(\d*)')
            match = re.match(regex_determine_decimal_part_length, att_string)
            if match.group(2):
                raise ValueError('Decimal part too long in provided value {}.'
                                 ' Only one decimal place is allowed'.format(att_value))
            att_string = match.group(1)
            regex_find_dot = re.compile(r'\.')
            att_string = re.sub(regex_find_dot, '', att_string)
        elif isinstance(att_value, int):
            att_value *= 10
            att_string = str(att_value)
        else:
            raise TypeError("Wrong type of value provided: {}.".format(type(att_value)))
        att_string = self._ensure_attenuation_value_string_has_correct_length(att_string)
        return att_string

    def _ensure_attenuation_value_string_has_correct_length(self, att_string):
        """ Fits given string to three characters format.
        Examples:
            1    -> 001
            11   -> 011
            111  -> 111
            1111 -> Throws exception
        :param att_string - attenuation value in string format
        :return: attenuation value in a three-digits format (str) """
        if len(att_string) > 3:
            raise ValueError("Expected value 1 to 3 characters long, but got {}"
                             "(last digit is decimal part)".format(att_string))
        else:
            att_string = "{:03d}".format(int(att_string))
        return att_string
